<script>
const BINARY_EXTENSIONS = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'ico', 'pdf', 'zip', 'tar', 'gz', 'woff', 'woff2', 'ttf', 'eot']

export default {
  name: 'FileViewer',
  props: {
    filePath: {
      type: String,
      required: true
    },
    fileName: {
      type: String,
      required: true
    }
  },
  data() {
    return {
      fileContent: '',
      fileMeta: {
        size: null,
        last_modification: null
      },
      editMode: false,
      editContent: '',
      saving: false,
      loading: false,
      error: null
    }
  },
  computed: {
    $api() {
      return this.$project.$api
    },
    fileExtension() {
      return this.fileName.split('.').pop()?.toLowerCase()
    },
    isBinary() {
      return BINARY_EXTENSIONS.includes(this.fileExtension)
    },
    validatedLanguage() {
      const lang = EXTENSION_LANGUAGE_MAP[this.fileExtension] || this.fileExtension
      try {
        if (lang && hljs.getLanguage(lang)) return lang
      } catch (ex) {
        console.warn(`Invalid language detected: ${lang}`, ex)
      }
      return 'markdown'
    }
  },
  mounted() {
    this.loadFile()
  },
  methods: {
    async loadFile() {
      this.loading = true
      this.error = null
      try {
        const { content, last_modification, size } = await this.$api.files.read('./' + this.filePath)
        this.fileContent = content
        this.fileMeta = { last_modification, size }
      } catch (ex) {
        console.error('Error reading file', ex)
        this.error = `Error reading "${this.filePath}"`
      } finally {
        this.loading = false
      }
    },
    startEdit() {
      this.editContent = this.fileContent
      this.editMode = true
    },
    cancelEdit() {
      this.editMode = false
      this.editContent = ''
    },
    async saveFile() {
      this.saving = true
      try {
        await this.$api.files.write(this.filePath, this.editContent)
        this.fileContent = this.editContent
        this.editMode = false
        this.$ui.addNotification({ text: `${this.fileName} saved` })
        const { last_modification, size } = await this.$api.files.read(this.filePath)
        this.fileMeta = { last_modification, size }
      } catch (ex) {
        console.error('Error saving file', ex)
        this.error = `Error saving "${this.filePath}"`
      } finally {
        this.saving = false
      }
    },
    copyContent() {
      this.$ui.copyTextToClipboard(this.fileContent)
    },
    formatSize(size) {
      if (size === null || size === undefined) return ''
      return size > 1024 ? `${Math.round(size / 1024)} KB` : `${size} B`
    }
  }
}
</script>
