        .sort((a, b) => {
          if (a.is_dir !== b.is_dir) return a.is_dir ? -1 : 1
          return a.name.localeCompare(b.name)
        })
    }
  },
  watch: {
    projectId() {
      this.currentPath = '.'
      this.clearSelection()
      this.loadDir(this.basePath)
    }
  },
  mounted() {
    this.loadDir(this.basePath)
  },
  methods: {
    async loadDir(path) {
      this.loading = true
      this.error = null
      try {
        const { files } = await this.$api.files.list(path)
        this.currentPath = path
        this.entries = files || []
        this.filter = ''
        this.clearSelection()
      } catch (ex) {
        console.error('Error listing files', ex)
        this.error = `Error listing "${path}"`
      } finally {
        this.loading = false
      }
    },
    entryPath(entry) {
      return this.currentPath === '.' ? entry.name : `${this.currentPath}/${entry.name}`
    },
    isEntrySelected(entry) {
      return this.selectedEntries.some(e => e.file_path === entry.file_path)
    },
    clearSelection() {
      this.selectedEntries = []
      this.lastSelectedIndex = null
    },
    handleEntryClick(entry, event) {
      const isCtrlClick = event.ctrlKey || event.metaKey
      const isShiftClick = event.shiftKey
      const index = this.visibleEntries.indexOf(entry)

      if (isShiftClick && this.lastSelectedIndex !== null) {
        this.selectRange(this.lastSelectedIndex, index)
      } else if (isCtrlClick) {
        this.toggleSelection(entry)
      } else {
        this.clearSelection()
        this.addSelection(entry)
        if (!entry.is_dir) {
          this.openFile(this.entryPath(entry), entry.name)
        }
      }

      this.lastSelectedIndex = index
    },
    addSelection(entry) {
      if (!this.isEntrySelected(entry)) {
        this.selectedEntries.push(entry)
      }
    },
    toggleSelection(entry) {
      const index = this.selectedEntries.findIndex(e => e.file_path === entry.file_path)
      if (index >= 0) {
        this.selectedEntries.splice(index, 1)
      } else {
        this.selectedEntries.push(entry)
      }
    },
    selectRange(startIndex, endIndex) {
      const start = Math.min(startIndex, endIndex)
      const end = Math.max(startIndex, endIndex)

      const rangeEntries = this.visibleEntries.slice(start, end + 1)
      this.selectedEntries = rangeEntries
    },
    openEntry(entry) {
      const path = this.entryPath(entry)
      if (entry.is_dir) {
        this.loadDir(path)
      } else {
        this.openFile(path, entry.name)
      }
    },
    openFile(path, name) {
      const tabId = `file-${path}`
      this.$storex.ui.addOpenFile({ path, name, tabId })
      this.$ui.showTab(tabId)
    },
    goToRoot() {
      this.clearSelection()
      this.loadDir('.')
    },
    goToPart(ix) {
      this.clearSelection()
      this.loadDir(this.breadcrumbParts.slice(0, ix + 1).join('/'))
    },
    goUp() {
      const parts = this.breadcrumbParts.slice(0, -1)
      this.clearSelection()
      this.loadDir(parts.length ? parts.join('/') : '.')
    },
    refresh() {
      this.loadDir(this.currentPath)
    },
    formatSize(size) {
      if (size === null || size === undefined) return ''
      return size > 1024 ? `${Math.round(size / 1024)} KB` : `${size} B`
    },
    onDragStart(event, entry) {
      this.draggedEntry = entry
      const filePath = this.entryPath(entry)
      event.dataTransfer.effectAllowed = 'copy'

      // If dragging a selected entry, include all selected files
      if (this.isEntrySelected(entry) && this.selectedEntries.length > 1) {
        const paths = this.selectedEntries.map(e => this.entryPath(e)).join('\n')
        event.dataTransfer.setData('text/plain', paths)
      } else {
        event.dataTransfer.setData('text/plain', filePath)
      }
    },
    onDragEnd() {
      this.draggedEntry = null
    }
  }
}
</script>
```

## Key Changes Made:

1. **New Data Properties:**
   - `selectedEntries`: Array to track selected file entries
   - `lastSelectedIndex`: Tracks the last clicked entry for shift+click range selection

2. **Selection Methods:**
   - `isEntrySelected()`: Check if entry is in selection
   - `clearSelection()`: Clear all selections
   - `addSelection()`: Add entry to selection
   - `toggleSelection()`: Toggle entry in/out of selection (Ctrl+Click)
   - `selectRange()`: Select range between two indices (Shift+Click)
   - `handleEntryClick()`: Main click handler that manages all selection modes

3. **Visual Feedback:**
   - Added blue background highlight for selected entries: `bg-blue-100 dark:bg-blue-900`
   - Added `transition-colors` for smooth selection changes

4. **Multi-Select Drag Support:**
   - When dragging a selected entry with multiple items selected, all selected files are included in the drag data (separated by newlines)

5. **Navigation Resets:**
   - Selection clears when navigating to different folders or changing projects

**Usage:**
- **Single click**: Select one entry and open files
- **Ctrl+Click**: Toggle individual entries on/off
- **Shift+Click**: Select range between last click and current click
- **Drag multiple**: When dragging a selected entry with others selected, all are included in the drag operation

Looking at your request, you want to update the drag-and-drop functionality in `FileExplorer.vue` to include file paths as a URL list format when multiple files are selected.

Currently, the `onDragStart` method sets file paths as plain text. We need to add the `text/uri-list` MIME type to properly support dropping files in applications that expect this format.

